   * @param {number} column - the 1-based column of the raw line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, column, message) {
    super(message)
    this.name = 'IniError'
    this.line = line
    this.column = column
  }
}

/** The 1-based column of the first non-space character of `raw`. */
function indent(raw) {
  return raw.length - raw.trimStart().length + 1
}

/**
 * The 1-based column of a value's own position: its first character, or, when it is
 * empty once trimmed, one past the line's last non-space character.
 * @param {string} raw - the untrimmed source line.
 * @param {string} trimmed - `raw.trim()`.
 * @param {number} split - the 0-based index of `=` within `trimmed`.
 */
function valueColumn(raw, trimmed, split) {
  const valueRaw = trimmed.slice(split + 1)
  if (valueRaw.trim() === '') return raw.trimEnd().length + 1
  return indent(raw) + split + 1 + (valueRaw.length - valueRaw.trimStart().length)
}

