      return text
    case 'duration': {
      const match = DURATION.exec(text)
      if (!match) throw new Error(`${declared.key} is not a duration: ${text}`)
      return String(Number(match[1]) * DURATION_SCALE[match[2]])
    }
    case 'list': {
      if (text === '') return ''
      const items = text.split(',').map(item => item.trim())
      if (items.some(item => item === '')) throw new Error(`${declared.key} has an empty item: ${text}`)
      const kept = []
      for (const item of items) if (!kept.includes(item)) kept.push(item)
