{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `dump <file>`, `get <file> <key>`, `load <base> <site>` and `origin <base> <site>`. */

import { existsSync, readFileSync } from 'node:fs'
import { EnvError, parseEnv } from './env.js'
import { IniError, parse as parseIni, parseEntries } from './ini.js'
import { merge } from './layer.js'
import { SETTINGS, coerce, setting } from './schema.js'

const USAGE = 'usage: cli.js dump <file>|get <file> <key>|load <base> <site>|origin <base> <site>'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** One INI layer, refused at its own position when the grammar rejects it. */
function iniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  try {
    return { name, values: parseIni(readFileSync(path, 'utf8')) }
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
}

/**
 * One INI layer for `load`/`origin`: strict about unknown keys, and carrying each value's
 * own position and originating layer for later reporting.
 */
function typedIniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  let entries
  try {
    entries = parseEntries(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const entry of entries) {
    if (setting(entry.key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${entry.key}`)
    values.set(entry.key, { text: entry.value, where: `${path}:${entry.line}:${entry.column}`, layer: name })
  }
  return { name, values }
}

/** The environment layer, read from standard input, refused at its own position. */
function envLayer() {
  let entries
  try {
    entries = parseEnv(readFileSync(0, 'utf8'))
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const entry of entries) {
    values.set(entry.key, { text: entry.value, where: `<stdin>:${entry.line}:${entry.column}`, layer: 'env' })
  }
  return { name: 'env', values }
}

const argv = process.argv.slice(2)
const mode = argv[0]
const arity = { dump: 2, get: 3, load: 3, origin: 3 }
if (argv.length !== arity[mode]) fail(USAGE)

const out = []
if (mode === 'dump' || mode === 'get') {
  const values = merge([iniLayer('file', argv[1])])
  const raw = key => (values.has(key) ? values.get(key) : setting(key).default)
  if (mode === 'dump') {
    for (const declared of SETTINGS) out.push(`${declared.key}=${raw(declared.key)}`)
  } else {
    if (setting(argv[2]) === undefined) fail(`unknown setting ${argv[2]}`)
    out.push(raw(argv[2]))
  }
} else {
  const layers = [typedIniLayer('base', argv[1]), typedIniLayer('site', argv[2]), envLayer()]
  const merged = merge(layers)
  if (mode === 'origin') {
    for (const declared of SETTINGS) out.push(`${declared.key} ${merged.has(declared.key) ? merged.get(declared.key).layer : 'default'}`)
  } else {
    for (const declared of SETTINGS) {
      const winning = merged.get(declared.key)
      const text = winning ? winning.text : declared.default
      try {
        out.push(`${declared.key}=${coerce(declared, text)}`)
      } catch (error) {
        fail(`${winning.where}: ${error.message}`)
      }
    }
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))
"}

