/**
 * One INI layer for `load`/`origin`: strict about unknown keys, and carrying each value's
 * own position and originating layer for later reporting.
 */
function typedIniLayer(name, path) {
  if (!existsSync(path)) fail(`cannot read ${path}`)
  let entries
  try {
    entries = parseEntries(readFileSync(path, 'utf8'))
  } catch (error) {
    if (!(error instanceof IniError)) throw error
    return fail(`${path}:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const entry of entries) {
    if (setting(entry.key) === undefined) fail(`${path}:${entry.line}:${entry.column}: unknown setting ${entry.key}`)
    values.set(entry.key, { text: entry.value, where: `${path}:${entry.line}:${entry.column}`, layer: name })
  }
  return { name, values }
}

/** The environment layer, read from standard input, refused at its own position. */
function envLayer() {
  let entries
  try {
    entries = parseEnv(readFileSync(0, 'utf8'))
  } catch (error) {
    if (!(error instanceof EnvError)) throw error
    return fail(`<stdin>:${error.line}:${error.column}: ${error.message}`)
  }
  const values = new Map()
  for (const entry of entries) {
    values.set(entry.key, { text: entry.value, where: `<stdin>:${entry.line}:${entry.column}`, layer: 'env' })
  }
  return { name: 'env', values }
}

